// === CONFIGURATION — edit these variables ===
const CONFIG = {
  GITHUB_OWNER: 'claude-builders-bounty',     // GitHub username or org
  GITHUB_REPO: 'claude-builders-bounty',       // Repository name
  LANGUAGE: 'EN',                              // 'EN' or 'FR'
  DELIVERY_TYPE: 'slack',                      // 'slack', 'discord', or 'email'
  SLACK_WEBHOOK: 'https://hooks.slack.com/services/YOUR_WEBHOOK',
  DISCORD_WEBHOOK: 'https://discord.com/api/webhooks/YOUR_WEBHOOK',
  EMAIL_TO: 'dev-team@yourcompany.com'
};

// Calculate date range: last 7 days
const now = new Date();
const since = new Date(now.getTime() - 7 * 24 * 60 * 60 * 1000);
const sinceISO = since.toISOString();
const untilISO = now.toISOString();

console.log(`Generating weekly summary for ${CONFIG.GITHUB_OWNER}/${CONFIG.GITHUB_REPO}`);
console.log(`Period: ${sinceISO} to ${untilISO}`);

return [{
  json: {
    ...CONFIG,
    since_date: sinceISO,
    until_date: untilISO,
    week_label: `Week of ${since.toLocaleDateString('en-US', { month: 'short', day: 'numeric' })} – ${now.toLocaleDateString('en-US', { month: 'short', day: 'numeric', year: 'numeric' })}`
  }
}];

// Merge all GitHub data into a structured summary
const config = $('Set Config & Date Range').first().json;
const since = new Date(config.since_date);

// Process commits
const commits = $('Fetch Commits').first().json;
const commitList = (Array.isArray(commits) ? commits : []).map(c => ({
  sha: c.sha?.substring(0, 7),
  author: c.commit?.author?.name || c.author?.login,
  message: c.commit?.message?.split('\n')[0] || '',
  date: c.commit?.author?.date
}));

// Process issues
const issues = $('Fetch Closed Issues').first().json;
const closedIssues = (Array.isArray(issues) ? issues : [])
  .filter(i => !i.pull_request && new Date(i.closed_at) >= since)
  .map(i => ({
    number: i.number,
    title: i.title,
    closed_by: i.closed_by?.login,
    labels: i.labels?.map(l => l.name).join(', ')
  }));

// Process PRs
const prs = $('Fetch Merged PRs').first().json;
const mergedPRs = (Array.isArray(prs) ? prs : [])
  .filter(p => p.merged_at && new Date(p.merged_at) >= since)
  .map(p => ({
    number: p.number,
    title: p.title,
    author: p.user?.login,
    merged_at: p.merged_at
  }));

// Build stats
const uniqueAuthors = [...new Set(commitList.map(c => c.author).filter(Boolean))];

console.log(`Stats: ${commitList.length} commits, ${closedIssues.length} issues, ${mergedPRs.length} merged PRs`);

return [{
  json: {
    config,
    week_label: config.week_label,
    repo: `${config.GITHUB_OWNER}/${config.GITHUB_REPO}`,
    stats: {
      total_commits: commitList.length,
      unique_contributors: uniqueAuthors.length,
      closed_issues: closedIssues.length,
      merged_prs: mergedPRs.length
    },
    commits: commitList.slice(0, 30),
    closed_issues: closedIssues.slice(0, 20),
    merged_prs: mergedPRs.slice(0, 15),
    contributors: uniqueAuthors
  }
}];

