// Build the final formatted message for delivery
const data = $('Aggregate GitHub Data').first().json;
const claudeResponse = $input.first().json;

const narrative = claudeResponse.content?.[0]?.text || 'Summary unavailable.';
const stats = data.stats;

// Format for different platforms
const slackMessage = {
  text: `📊 *Weekly Dev Summary: ${data.repo}*\n_${data.week_label}_`,
  blocks: [
    {
      type: 'header',
      text: { type: 'plain_text', text: `📊 Weekly Dev Summary: ${data.repo}` }
    },
    {
      type: 'section',
      text: {
        type: 'mrkdwn',
        text: `*${data.week_label}*\n\n*Quick Stats:* ${stats.total_commits} commits · ${stats.merged_prs} PRs merged · ${stats.closed_issues} issues closed · ${stats.unique_contributors} contributors`
      }
    },
    {
      type: 'section',
      text: { type: 'mrkdwn', text: narrative }
    },
    {
      type: 'context',
      elements: [{ type: 'mrkdwn', text: `Generated by n8n + Claude Sonnet · Every Friday 5pm` }]
    }
  ]
};

const discordMessage = {
  content: null,
  embeds: [{
    title: `📊 Weekly Dev Summary: ${data.repo}`,
    description: `**${data.week_label}**\n\n**Stats:** ${stats.total_commits} commits · ${stats.merged_prs} PRs · ${stats.closed_issues} issues closed · ${stats.unique_contributors} contributors\n\n${narrative}`,
    color: 0x4361EE,
    footer: { text: 'Generated by n8n + Claude Sonnet' }
  }]
};

const emailBody = `Weekly Dev Summary: ${data.repo}\n${data.week_label}\n\nStats: ${stats.total_commits} commits, ${stats.merged_prs} PRs merged, ${stats.closed_issues} issues closed, ${stats.unique_contributors} contributors\n\n${narrative}`;

return [{
  json: {
    config: data.config,
    narrative,
    slack_payload: slackMessage,
    discord_payload: discordMessage,
    email_body: emailBody,
    subject: `Dev Summary: ${data.repo} — ${data.week_label}`,
    delivery_type: data.config.DELIVERY_TYPE
  }
}];
